body.script:
//
// Theme Initializer to prevent flashing
(function() {
  const savedTheme = localStorage.getItem('theme');
  if (savedTheme) {
    document.documentElement.setAttribute('data-theme', savedTheme);
  } else if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
    document.documentElement.setAttribute('data-theme', 'dark');
  }
})();

// Interactive Theme Switcher logic
const themeToggleBtn = document.getElementById('themeToggle');
const lightIcon = themeToggleBtn.querySelector('.light-icon');
const darkIcon = themeToggleBtn.querySelector('.dark-icon');

function updateToggleIcons(theme) {
  if (theme === 'dark') {
    lightIcon.style.display = 'none';
    darkIcon.style.display = 'inline';
  } else {
    lightIcon.style.display = 'inline';
    darkIcon.style.display = 'none';
  }
}

// Set initial icons status
const currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
updateToggleIcons(currentTheme);

themeToggleBtn.addEventListener('click', () => {
  const activeTheme = document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
  document.documentElement.setAttribute('data-theme', activeTheme);
  localStorage.setItem('theme', activeTheme);
  updateToggleIcons(activeTheme);
});

// Mobile Hamburger Dropdown Menu
const burgerMenu = document.getElementById('burgerMenu');
const navbarLinks = document.getElementById('navbarLinks');

burgerMenu.addEventListener('click', () => {
  navbarLinks.classList.toggle('active');
  // Subtle transformation of burger bars
  const bars = burgerMenu.querySelectorAll('.burger-bar');
  bars[0].style.transform = navbarLinks.classList.contains('active') ? 'rotate(45deg) translate(6px, 6px)' : 'none';
  bars[1].style.opacity = navbarLinks.classList.contains('active') ? '0' : '1';
  bars[2].style.transform = navbarLinks.classList.contains('active') ? 'rotate(-45deg) translate(5px, -5px)' : 'none';
});

// Close mobile menu on clicking any navigation link
const navLinksArray = document.querySelectorAll('.navbar-link');
navLinksArray.forEach(link => {
  link.addEventListener('click', () => {
    navbarLinks.classList.remove('active');
    const bars = burgerMenu.querySelectorAll('.burger-bar');
    bars[0].style.transform = 'none';
    bars[1].style.opacity = '1';
    bars[2].style.transform = 'none';

    // Highlight active link
    navLinksArray.forEach(l => l.classList.remove('active'));
    link.classList.add('active');
  });
});

// Floating Navbar Translucent backdrop update on scroll
window.addEventListener('scroll', () => {
  const header = document.querySelector('.navbar-wrapper');
  if (window.scrollY > 20) {
    header.style.boxShadow = 'var(--shadow-sm)';
  } else {
    header.style.boxShadow = 'none';
  }
});

// Interactive App Detail Database & Modal Population
const appsDatabase = {
  cineprompt: {
    name: 'CinePrompt AI',
    category: 'AI / Creativity',
    desc: 'Discover and explore cinematic AI prompts for image and video generation.',
    why: 'Built to empower independent filmmakers, conceptual artists, and AI creators with a library of robust, production-ready cinematic lighting, camera angles, and rendering recipes.',
    features: [
      'Pre-built aspect-ratio calculators & grid ratios',
      'Cinematic camera lens simulation selectors (e.g., Anamorphic, 35mm)',
      'High-fidelity custom lighting variables',
      'One-click clipboard copy with platform compatibility indicators'
    ],
    platforms: ['Android', 'Google Play', 'Web App Client']
  },
  turtlex: {
    name: 'TurtleX IDE',
    category: 'Developer Tools',
    desc: 'A mobile-first development environment built for modern web development.',
    why: 'Built because we believe developer workflow should not be tethered exclusively to high-end workstations. TurtleX lets you write production web applications fully on mobile-optimized local sandboxes.',
    features: [
      'Real-time built-in browser previews and debugger panel',
      'Offline packages and npm modules emulator',
      'Git repositories push, fetch, and pull capabilities',
      'Full customization shortcuts & auto-indent code engines'
    ],
    platforms: ['Android', 'Samsung Galaxy Store', 'Tablet OS']
  },
  krypton: {
    name: 'Krypton Key',
    category: 'Utility / Security',
    desc: 'Premium client-side offline password encryption and authentication keys generator.',
    why: 'We designed Krypton Key to store zero passwords on corporate clouds. Everything is fully client-side using industry-leading AES-256 local keys generators, guaranteeing 100% complete data ownership.',
    features: [
      'Military-grade local encryption (AES-256)',
      'Strict zero cloud connection or tracking services',
      'Elegant biometric app unlocking capabilities',
      'Standard physical storage keys import/export backup channels'
    ],
    platforms: ['Android', 'Offline Safe', 'F-Droid Available']
  }
};

function showAppDetail(appId) {
  const app = appsDatabase[appId];
  if (!app) return;

  document.getElementById('modalAppName').innerText = app.name;

  let featuresHtml = '';
  app.features.forEach(f => {
    featuresHtml += `<li class="showcase-feature-item" style="font-size:0.95rem; color:var(--color-text); margin-bottom:10px;"><span class="feature-check-icon"><svg class="icon-inline" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" style="width: 12px; height: 12px;"><path d="M20 6L9 17l-5-5"/></svg></span> ${f}</li>`;
  });

  let platformsHtml = '';
  app.platforms.forEach(p => {
    platformsHtml += `<span class="platform-badge">${p}</span>`;
  });

  const bodyHtml = `
    <div style="display:flex; flex-direction:column; gap:20px;">
      <div>
        <span class="showcase-badge" style="margin-bottom:10px;">${app.category}</span>
        <p style="font-size:1.1rem; color:var(--color-text); font-weight:500; line-height:1.5;">${app.desc}</p>
      </div>
      <div>
        <h4 style="font-size:1rem; font-weight:800; color:var(--color-text); margin-bottom:8px; text-transform:uppercase; letter-spacing:0.05em;">Why It Was Built</h4>
        <p style="color:var(--color-text-muted); font-size:0.95rem; line-height:1.6;">${app.why}</p>
      </div>
      <div>
        <h4 style="font-size:1rem; font-weight:800; color:var(--color-text); margin-bottom:12px; text-transform:uppercase; letter-spacing:0.05em;">Core Product Features</h4>
        <ul style="list-style:none;">
          ${featuresHtml}
        </ul>
      </div>
      <div>
        <h4 style="font-size:1rem; font-weight:800; color:var(--color-text); margin-bottom:12px; text-transform:uppercase; letter-spacing:0.05em;">Available Platforms</h4>
        <div style="display:flex; gap:10px; flex-wrap:wrap;">
          ${platformsHtml}
        </div>
      </div>
      <div style="margin-top:20px; display:flex; gap:12px;">
        <a class="btn btn-primary" href="https://play.google.com/store" target="_blank" rel="noopener noreferrer">Download on Play Store</a>
        <button class="btn btn-secondary" onclick="closeAppDetail()" type="button">Close details</button>
      </div>
    </div>
  `;

  document.getElementById('modalAppContent').innerHTML = bodyHtml;

  const modal = document.getElementById('appDetailModal');
  modal.style.display = 'flex';
  document.body.style.overflow = 'hidden';
}

function closeAppDetail() {
  const modal = document.getElementById('appDetailModal');
  modal.style.display = 'none';
  document.body.style.overflow = 'auto';
}

// Handle interactive contact form submission
function handleContactSubmit(event) {
  event.preventDefault();
  const name = document.getElementById('contactName').value;
  const email = document.getElementById('contactEmail').value;
  const msg = document.getElementById('contactMessage').value;

  alert(`Thank you, ${name}! Your message has been sent successfully to SynFusion. We will get back to you shortly at ${email}.`);
  document.getElementById('contactForm').reset();
}
//
